solution:
def parse_cookie_header(header):
    cookies = {}
    for segment in header.split(";"):
        name, equals, value = segment.partition("=")      # cut at the first "="; `equals` is empty if there was none
        name = name.strip()
        if not equals or not name:
            continue                                      # not a cookie: no "=", or no name
        cookies.setdefault(name, value.strip())           # the first cookie with a name wins
    return cookies
